class Solution {
public:
    int distinctAverages(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        unordered_set<int> s;
        int l = 0, r = nums.size() - 1;
        while (l < r) s.insert(nums[l++] + nums[r--]);
        return s.size();
    }
};

