class Solution {
    public int distinctAverages(int[] nums) {
        List<Integer> a = new ArrayList<>();
        for (int x : nums) a.add(x);
        Set<Integer> s = new HashSet<>();
        while (a.size() >= 2) {
            int x = Collections.min(a); a.remove(Integer.valueOf(x));
            int y = Collections.max(a); a.remove(Integer.valueOf(y));
            s.add(x + y);
        }
        return s.size();
    }
}

